import {initMobile} from './mobile.js?v=60';
import {localDate,localMinute,fromLocal,dateShift,zoneLabel} from './time.js?v=60';
import {icon,esc} from './icons.js';
import {initDisplay,displayButton} from './display.js?v=60';
import {landing} from './landing.js?v=60';
const tg=window.Telegram?.WebApp,local=['localhost','127.0.0.1'].includes(location.hostname),root=document.querySelector('#app'),sheet=document.querySelector('#dialog');
const cats={beauty:'Маникюр и красота',barber:'Барбер',hair:'Парикмахер',brows:'Бровист',cosmetology:'Косметолог',massage:'Массаж',cleaning:'Клининг',photo:'Фотограф',education:'Репетитор',auto:'Автомастер',repair:'Мастер ремонта',other:'Другое'};
const labels={pending:'Ожидает подтверждения',confirmed:'Подтверждено',done:'Завершено',cancelled:'Отменено',no_show:'Не пришёл'};
const zone=()=>booking?.tenant?.timezone||(S.mode==='client'?S.tenant:S.own)?.timezone||'Europe/Moscow';
const money=v=>new Intl.NumberFormat('ru-RU').format(v||0)+' ₽',day=(n=0)=>dateShift(localDate(Date.now()/1000,zone()),n),date=t=>localDate(t,zone()),time=t=>new Date(t*1000).toLocaleTimeString('ru-RU',{timeZone:zone(),hour:'2-digit',minute:'2-digit'}),dateLabel=d=>new Date(d+'T12:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'long'}),shift=dateShift,minute=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0'),parseTime=s=>{const [h,m]=s.split(':').map(Number);return h*60+m},unix=(d,t)=>fromLocal(d,parseTime(t),zone());
const S={me:null,mode:'specialist',page:'landing',role:'client',tenant:null,own:null,bookings:[],clients:[],blocks:[],date:localDate(),calendar:'day',tour:false,tourStep:0,prefs:{},step:0,tab:'upcoming',loading:false,preview:false,photo:'',draft:{name:'',category:'beauty',tagline:'',address:'',phone:'',photo:'',service_name:'',price:1500,duration:60,description:'',schedule:[null,...Array.from({length:5},()=>({start:540,end:1080})),null]}};
let renderVersion=0,booking=null,toastTimer,pollBusy=false,manualDate=day(),manualAt=null,manualClient=null,manualNewClient={name:'',phone:''};
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
async function api(path,options={}){let r;try{r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-Telegram-Init-Data':tg?.initData||'',...(local?{'X-Demo-Role':S.role}:{}),...options.headers}})}catch{throw Error('Не удалось соединиться. Проверьте интернет и попробуйте снова.')}let b;try{b=await r.json()}catch{throw Error('Сервис временно недоступен')}if(!r.ok)throw Object.assign(Error(r.status>=500?'Сервис временно недоступен. Попробуйте ещё раз.':b.error||'Не удалось сохранить'),{status:r.status});return b}
const post=(path,b)=>api(path,{method:'POST',body:JSON.stringify(b)});
function stored(key,value){try{const k='takt2:'+String(S.me?.id||'guest')+':'+key;if(value!==undefined)localStorage.setItem(k,value);return localStorage.getItem(k)}catch{return null}}
const isClient=()=>S.mode==='client',c=()=>isClient()?S.tenant:S.own,link=id=>S.own?.id===id&&S.own.username?(S.own.short_base||location.origin)+'/'+S.own.username:'https://t.me/takt_service_bot?startapp=c_'+id;
const initials=name=>String(name||'Т').trim().split(/\s+/).filter(Boolean).slice(0,3).map(x=>Array.from(x)[0]||'').join('').toUpperCase()||'Т';
const imageTag=(photo,name,cls='portrait')=>photo?`<img class="${cls}" src="${esc(photo)}" alt="${esc(name)}">`:`<span class="${cls} initials">${esc(initials(name))}</span>`;
function nav(){return isClient()?[['client','beauty','Записаться'],['my','calendar','Мои записи'],['profile','user','Профиль']]:[['dashboard','home','Главная'],['calendar','calendar','Расписание'],['clients','user','Клиенты'],['more','grid','Ещё']]}
function heading(title,sub='',action=''){return `<div class="page-title"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</div>`}
function button(title,page,style='primary'){return `<button class="${style}" data-page="${page}">${title}</button>`}
function empty(title,description,cta=''){return `<div class="empty-state">${icon('calendar')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${cta}</div>`}
function skeleton(){return '<div class="skeletons" aria-label="Загрузка" role="status"><div></div><div></div><div></div></div>'}
function shell(){const simple=S.tour||!S.own&&!isClient()||S.page==='landing'||S.page==='register';const menu=nav().map(([p,i,t])=>`<button data-page="${p}" class="${S.page===p||p==='more'&&['services','settings','share','analytics','subscription','profile'].includes(S.page)?'active':''}">${icon(i)}<span>${t}</span></button>`).join('');root.innerHTML=`<div class="v2-layout ${simple?'simple':''} ${isClient()?'client-mode':''}">${!simple?`<aside class="v2-sidebar"><button class="brand" data-page="${isClient()?'client':'dashboard'}"><span class="brand-mark">т</span>${isClient()?esc(S.tenant?.name||'Моя запись'):'такт'}</button><p class="sidebar-caption">${isClient()?'Ваша страница записи':'Мой сервис онлайн-записи'}</p><nav>${menu}</nav><div class="sidebar-bottom">${isClient()?'Удобное время для вас':'Ваше дело. В вашем ритме.'}</div></aside>`:''}<main class="v2-main"><header class="v2-top"><button class="brand" data-page="${isClient()?'client':S.own?'dashboard':'landing'}"><span class="brand-mark">т</span>${isClient()?'Моя запись':'такт'}</button><div class="topbar-actions">${displayButton()}${S.me?.owner?'<button class="secondary admin-entry" data-page="admin">Админ-панель</button>':''}${!simple?`<button class="account-button" data-page="profile" aria-label="Мой профиль">${imageTag(c()?.photo,S.me?.name,'small-avatar')}</button>`:''}</div></header>${local?`<div class="demo-bar"><span>Локальная проверка</span><select id="demo-role" aria-label="Тестовая роль">${[['client','Клиент'],['company','Специалист'],['owner','Владелец']].map(([v,t])=>`<option value="${v}" ${S.role===v?'selected':''}>${t}</option>`).join('')}</select></div>`:''}${S.preview?'<div class="preview-banner">Так вашу страницу увидит клиент<button class="text-button" id="exit-preview">В кабинет</button></div>':''}${!S.tour&&!['dashboard','client','landing'].includes(S.page)?'<button id="app-back" class="text-button page-back">← Назад</button>':''}<div id="view"></div><footer class="v2-footer"><span>${isClient()?'Онлайн-запись · Такт':'Такт · Ваше время принадлежит вам'}</span><button class="text-button" id="guide">Как это работает</button></footer></main>${!simple?`<nav class="v2-bottom" aria-label="Основная навигация">${menu}</nav>`:''}</div>`}
async function init(){booking=null;root.innerHTML='<div class="startup">такт<span>Готовим ваше пространство…</span></div>';try{try{S.me=await api('/me');messageAllowed=!!S.me.allows_write}catch(e){if(e.status!==401)throw e;S.me=null}S.prefs=S.me?await api('/v2/preferences'):{};if(S.me&&!messageAllowed)try{messageAllowed=(await api('/v5/notifications')).state==='allowed'}catch{}const params=new URLSearchParams(location.search),start=tg?.initDataUnsafe?.start_param||params.get('company');let invite=start&&!['register','client'].includes(start)?start.replace(/^(c_|master_)/,''):null;S.own=null;S.tenant=null;S.preview=false;const username=params.get('username')||(start?.startsWith('u_')?start.slice(2):null);if(username)invite=(await api('/v2/resolve?username='+encodeURIComponent(username))).company_id;
if(invite){S.mode='client';try{S.tenant=await api('/v2/page/'+encodeURIComponent(invite));if(S.me)await post('/v2/context',{company_id:invite});stored('tenant',invite)}catch{S.tenant=null}S.page='client'}
else{if(S.me){const own=await api('/companies');S.own=own[0]||null}const context=S.me?await api('/v2/context'):{};const previous=context.company_id||stored('tenant');if(!S.own&&start!=='register'&&(previous||start==='client')){S.mode='client';if(previous)try{S.tenant=await api('/v2/page/'+previous)}catch{}S.page='client'}else{S.mode='specialist';S.page=S.own?'dashboard':start==='register'?'register':'landing'}}
S.tour=!((S.prefs[S.mode+'_intro']||0)>=2||stored('tour-'+S.mode)==='2');S.tourStep=0;S.date=day();if(params.get('booking')&&!S.tour){S.page=isClient()?'my':'calendar'}else if(params.get('view')==='calendar'&&S.own){S.page='calendar';if(/^\d{4}-\d{2}-\d{2}$/.test(params.get('date')||''))S.date=params.get('date')}if(params.get('view')==='admin'&&S.me?.owner)S.page='admin';await render();if(params.get('booking')&&!S.tour)openLinkedBooking().catch(e=>toast(e.message));}catch(e){root.innerHTML=`<div class="startup">Такт<span>${esc(e.message)}</span><button id="retry-init" class="primary">Повторить</button></div>`}}
async function refreshOwn(){S.own=(await api('/companies'))[0]||null}
async function workData(){if(!S.own)return;const id=S.own.id;[S.bookings,S.blocks]=await Promise.all([api('/bookings?scope=company&company='+id),api('/v2/blocks?company='+id)])}
async function render(){const version=++renderVersion;if(S.page==='admin'&&!S.me?.owner)S.page='landing';if(isClient()&&!['client','my','profile','admin'].includes(S.page))S.page='client';if(!isClient()&&!S.own&&!['landing','register','admin'].includes(S.page))S.page='landing';shell();const view=document.querySelector('#view');if(S.tour&&S.page!=='admin'){view.innerHTML=tour();return}view.innerHTML=skeleton();try{
if(!isClient()&&['dashboard','calendar','clients','analytics'].includes(S.page)){await workData();if(S.page==='clients')S.clients=await api('/v2/clients?company='+S.own.id)}
if(isClient()&&S.page==='my'&&S.me)S.bookings=await api('/bookings');if(version!==renderVersion)return;
if(S.page==='admin'){S.admin=await api('/v5/admin');if(version!==renderVersion)return}const pages={admin:adminPage,landing,register:registration,dashboard,calendar:calendarPage,clients:clientsPage,more,services:servicesPage,share:sharePage,settings:settingsPage,subscription:subscriptionPage,analytics:analyticsPage,client:clientPage,my:myBookings,profile};view.innerHTML=(pages[S.page]||landing)();view.classList.remove('screen-enter');void view.offsetWidth;view.classList.add('screen-enter');if(S.page==='settings')loadDeliveryStatus();if(S.page==='client'&&S.me&&!S.preview)loadClientNext();
}catch(e){if(version===renderVersion)view.innerHTML=empty('Не удалось загрузить',e.message,'<button class="primary" id="refresh">Повторить</button>')}}
function tour(){if(!isClient())return landing();const x=S.tenant;return `<section class="client-intro">${imageTag(x?.photo,x?.name)}<span class="eyebrow">ВАША ЛИЧНАЯ СТРАНИЦА ЗАПИСИ</span><h1>Запись к ${esc(x?.name||'специалисту')}</h1><p>Выберите услугу и удобное время — всё займёт меньше минуты.</p><button class="primary" id="skip-tour">Записаться ${icon('arrow')}</button><ol class="v3-steps">${['Выберите услугу','Найдите удобное время','Подтвердите запись','За 24 часа подтвердите визит, за 2 часа Takt напомнит 🔔'].map((t,i)=>`<li><span>0${i+1}</span><p>${t}</p></li>`).join('')}</ol><p class="note">Ваши будущие встречи и история — в разделе «Мои записи».</p></section>`}
async function openLinkedBooking(){const p=new URLSearchParams(location.search),id=p.get('booking');if(!id||!S.bookings.some(b=>b.id===id))return;visitActions(id);const action=p.get('action');if(action==='client'&&S.own){S.clients=await api('/v2/clients?company='+S.own.id);const b=S.bookings.find(x=>x.id===id);clientDetails(b.user_id)}if(action==='move')sheet.querySelector('[data-move]')?.click();if(action==='cancel')sheet.querySelector('[data-cancel]')?.click();history.replaceState(null,'',location.pathname+(S.tenant?'?company='+encodeURIComponent(S.tenant.id):''))}
async function finishTour(){if(S.me)try{await post('/v2/preferences',{mode:S.mode})}catch{toast('Знакомство сохранено на этом устройстве')}stored('tour-'+S.mode,'2');S.tour=false;if(isClient()&&new URLSearchParams(location.search).has('booking'))S.page='my';await render();openLinkedBooking().catch(e=>toast(e.message));scrollTo({top:0})}
function login(){return empty('Откройте в Telegram','Для записи и личного кабинета нужен ваш Telegram-аккаунт.',`<a class="primary" href="https://t.me/takt_service_bot?startapp=${isClient()&&S.tenant?(S.tenant.username?'u_'+S.tenant.username:'c_'+S.tenant.id):'register'}">Открыть приложение</a>`)}
function photoField(key,current=''){return `<label class="photo-picker">${imageTag(current,'Фото','upload-avatar')}<span>Добавить фото<small>JPG, PNG · сожмём автоматически</small></span><input type="file" accept="image/jpeg,image/png,image/webp" data-photo="${key}" aria-label="Загрузить фото"></label>`}
function intervalInputs(i,d){return `<div class="work-interval"><input type="time" name="start${i}" value="${minute(d.start)}" step="300" aria-label="Начало работы"><span>—</span><input type="time" name="end${i}" value="${minute(d.end===1440?0:d.end)}" step="300" aria-label="Конец работы"><button type="button" class="text-button" data-remove-interval aria-label="Удалить интервал">×</button></div>`}
function scheduleFields(hours){return `<div class="schedule-editor">${[1,2,3,4,5,6,0].map(i=>{const d=hours[i],parts=d?(Array.isArray(d)?d:[d]):[{start:540,end:1080}];return `<div class="work-day"><label class="day-check"><input type="checkbox" name="day${i}" ${d?'checked':''}><span>${['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'][i]}</span></label><div class="work-intervals" data-day-intervals="${i}">${parts.map(d=>intervalInputs(i,d)).join('')}</div><button type="button" class="text-button" data-add-interval="${i}">＋ Интервал после перерыва</button><button type="button" class="text-button" data-copy-day="${i}">Применить к другим дням</button></div>`}).join('')}</div><p class="note">Промежутки между интервалами — перерывы. Выключите день, чтобы сделать его выходным. Конец в 00:00 означает полночь.</p>`}
function readSchedule(f){return Array.from({length:7},(_,i)=>f.get('day'+i)?f.getAll('start'+i).map((v,k)=>({start:parseTime(v),end:parseTime(f.getAll('end'+i)[k])||1440})):null)}
function registration(){if(!S.me)return login();if(S.own)return empty('Ваша страница уже готова','Все услуги находятся в вашем личном кабинете.',button('Перейти в кабинет','dashboard'));const b=S.draft;return `${heading('Создадим вашу страницу','Короткая настройка — и можно приглашать клиентов.')}<div class="setup-progress">${['О вас','Первая услуга','Расписание'].map((t,i)=>`<span class="${S.step===i?'active':''}">${i+1}. ${t}</span>`).join('')}</div><section class="editor-card"><form id="register-form"><span class="eyebrow">Шаг ${S.step+1} из 3</span><h2>${['Давайте познакомимся','С чего начнём запись?','Когда вы принимаете?'][S.step]}</h2>${S.step===0?`${photoField('draft',b.photo)}<label>Имя или название<input name="name" value="${esc(b.name)}" minlength="2" maxlength="80" required placeholder="Например, Давуд · барбер"></label><label>Чем вы занимаетесь<select name="category">${Object.entries(cats).map(([v,t])=>`<option value="${v}" ${b.category===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Коротко о вас<textarea name="tagline" maxlength="160" placeholder="Ваш подход, опыт или специализация">${esc(b.tagline)}</textarea></label><label>Адрес или формат работы<input name="address" value="${esc(b.address)}" maxlength="200" placeholder="Адрес, выезд или онлайн"></label><label>Телефон · по желанию<input type="tel" name="phone" value="${esc(b.phone)}" maxlength="24"></label>`:S.step===1?`<label>Название услуги<input name="service_name" value="${esc(b.service_name)}" minlength="2" maxlength="120" required placeholder="Например, стрижка + борода"></label><div class="form-grid"><label>Стоимость, ₽<input type="number" name="price" min="0" max="1000000" value="${b.price}" required></label><label>Длительность, мин<input type="number" name="duration" min="15" max="480" step="5" value="${b.duration}" required></label></div><label>Что входит<textarea name="description" maxlength="700">${esc(b.description)}</textarea></label>`:scheduleFields(b.schedule)}<div class="form-error" role="alert"></div><div class="actions">${S.step?'<button type="button" class="secondary" id="register-back">Назад</button>':''}<button class="primary" type="submit">${S.step===2?'Создать страницу':'Продолжить'} ${icon('arrow')}</button></div></form></section>`}
function saveDraft(){const form=document.querySelector('#register-form');if(!form)return;const f=new FormData(form);if(S.step===2)S.draft.schedule=readSchedule(f);else Object.assign(S.draft,Object.fromEntries(f))}
const active=b=>['pending','confirmed'].includes(b.status),future=b=>active(b)&&b.ends_at>Date.now()/1000;
const attendanceInfo=b=>({coming:['coming','✅ Клиент подтвердил визит'],not_coming:['not_coming','❌ Клиент не сможет прийти'],unknown:['unknown','⚪ Клиент ещё не подтвердил']}[b.attendance_state||'unknown']);
const until=t=>{const sec=Math.max(0,t-Date.now()/1000),m=Math.round(sec/60);if(m<60)return `через ${m} мин`;const h=Math.floor(m/60),r=m%60;if(h<24)return `через ${h} ч${r?' '+r+' мин':''}`;const d=Math.floor(h/24);return `через ${d} дн`};
const trialText=x=>!x?.subscription?'':x.subscription.status==='trial'?`Пробный период · ${x.subscription.days_left} дн.`:x.subscription.status==='active'?'Подписка активна':'Пробный период закончился';
function bookingCard(b,admin=false){const att=admin?attendanceInfo(b):null;return `<article class="visit-card" data-booking-card="${b.id}"><div class="visit-time"><strong>${time(b.starts_at)}</strong><span>${dateLabel(date(b.starts_at))}</span></div><div class="visit-info"><h3>${esc(b.service_name)}</h3><p>${esc(admin?b.name:b.company_name||S.tenant?.name||'Специалист')}</p><span class="badge ${b.status}">${labels[b.status]||b.status}</span>${att?`<span class="attendance visit-confirmation ${att[0]}">${att[1]}</span>`:''}</div><div class="visit-end"><strong>${money(b.price)}</strong><button class="more-button" data-visit="${b.id}" aria-label="Действия с записью">•••</button></div></article>`}
function dashboard(){const now=Date.now()/1000,today=S.bookings.filter(b=>date(b.starts_at)===day()),futureRows=S.bookings.filter(future).sort((a,b)=>a.starts_at-b.starts_at),next=futureRows[0],pending=futureRows.filter(b=>b.status==='pending'),earned=today.filter(b=>b.status!=='cancelled').reduce((a,b)=>a+b.price,0),sub=S.own.subscription;const pendingBlock=pending.length?`<section class="pending-panel"><div class="section-heading"><h2>Требуют подтверждения</h2><strong>${pending.length}</strong></div>${pending.slice(0,4).map(b=>`<div class="pending-row"><div><strong>${time(b.starts_at)} · ${esc(b.name)}</strong><p>${esc(b.service_name)} · ${dateLabel(date(b.starts_at))}</p></div><div class="actions"><button class="primary" data-status="confirmed" data-id="${b.id}">Подтвердить</button><button class="text-button" data-visit="${b.id}">Открыть</button></div></div>`).join('')}</section>`:'';const nextBlock=next?(()=>{const att=attendanceInfo(next),duration=Math.round((next.ends_at-next.starts_at)/60);return `<section class="next-visit"><span class="eyebrow">Следующий клиент ${until(next.starts_at)} · ${dateLabel(date(next.starts_at))}</span><div><h2>${time(next.starts_at)}</h2><div><strong>${esc(next.name)}</strong><p>${esc(next.service_name)} · ${duration} мин · ${money(next.price)}</p><div class="next-meta"><span class="badge ${next.status}">${labels[next.status]}</span><span class="attendance ${att[0]}">${att[1]}</span></div></div></div><div class="actions"><button class="secondary" data-visit="${next.id}">Открыть запись</button></div></section>`})():`<div class="dashboard-empty"><h3>Сегодня записей нет 👋</h3><p>Свободные окна доступны клиентам для онлайн-записи.</p><div class="actions"><button class="primary" data-page="share">Поделиться ссылкой</button><button class="secondary" data-manual>＋ Добавить запись</button></div></div>`;return `${heading('Добрый день, '+S.own.name,'Сегодня · '+dateLabel(day()))}${sub?`<button class="subscription-strip ${sub.status==='expired'?'expired':''}" data-page="subscription"><span>${esc(trialText(S.own))}</span><strong>${sub.status==='trial'?'7 дней бесплатно → 590 ₽/мес':sub.status==='expired'?'590 ₽/месяц':'Takt'}</strong></button>`:''}<section class="today-summary"><div><span>Записей сегодня</span><strong>${today.filter(active).length}</strong></div><div><span>Стоимость записей</span><strong>${money(earned)}</strong></div><div><span>Вариантов времени</span><strong id="free-count">…</strong><small id="free-label"></small></div></section>${pendingBlock}${nextBlock}<div class="section-heading"><h2>Быстрые действия</h2></div><div class="quick-grid"><button data-manual>${icon('calendar')}Добавить запись</button><button data-edit-service="new">${icon('grid')}Добавить услугу</button><button data-page="share">${icon('link')}Моя ссылка</button><button id="block-time">${icon('clock')}Закрыть время</button></div><div class="section-heading"><h2>Записи на сегодня</h2><button data-page="calendar" class="text-button">Все →</button></div>${today.filter(b=>b.status!=='cancelled').sort((a,b)=>a.starts_at-b.starts_at).map(b=>bookingCard(b,true)).join('')||'<div class="dashboard-empty"><h3>На сегодня всё свободно</h3><p>Можно поделиться ссылкой или добавить запись вручную.</p></div>'}`}
function calendarPage(){const n=S.calendar==='week'?7:S.calendar==='month'?new Date(Number(S.date.slice(0,4)),Number(S.date.slice(5,7)),0).getDate():1,start=S.calendar==='month'?S.date.slice(0,8)+'01':S.calendar==='week'?shift(S.date,-((new Date(S.date+'T12:00Z').getUTCDay()+6)%7)):S.date;const cards=Array.from({length:n},(_,i)=>{const d=shift(start,i),rows=S.bookings.filter(b=>date(b.starts_at)===d&&b.status!=='cancelled').sort((a,b)=>a.starts_at-b.starts_at),blocks=S.blocks.filter(b=>date(b.starts_at)<=d&&date(b.ends_at)>=d);return `<section class="calendar-day"><button class="calendar-date" data-date="${d}">${dateLabel(d)} <span>${new Date(d+'T12:00Z').toLocaleDateString('ru-RU',{weekday:'short'})}</span></button>${rows.map(b=>`<button class="calendar-event ${b.status}" data-visit="${b.id}"><strong>${time(b.starts_at)}–${time(b.ends_at)}</strong><span>${esc(b.service_name)}</span><small>${esc(b.name)} · ${money(b.price)}</small>${b.attendance_state&&b.attendance_state!=='unknown'?`<span class="attendance-mini ${b.attendance_state}">${b.attendance_state==='coming'?'✓ Клиент придёт':'Клиент не сможет'}</span>`:''}</button>`).join('')}${blocks.map(b=>`<button class="calendar-block" data-unblock="${b.id}">${time(b.starts_at)}–${time(b.ends_at)}<br>${esc(b.label)}</button>`).join('')}${!rows.length&&!blocks.length?'<p class="calendar-free">Нет записей</p>':''}${S.calendar==='day'?freeTimeline(d,rows,blocks):''}</section>`}).join('');return `${heading('Расписание','Ваши встречи и свободное время.', '<button class="primary" data-manual>＋ Запись</button>')}<div class="calendar-toolbar"><div class="segmented">${[['day','День'],['week','Неделя'],['month','Месяц']].map(([v,t])=>`<button data-calendar="${v}" class="${S.calendar===v?'selected':''}">${t}</button>`).join('')}</div><div class="date-controls"><button class="secondary" data-shift="-1" aria-label="Назад">‹</button><input id="calendar-date" type="date" value="${S.date}" aria-label="Дата"><button class="secondary" data-shift="1" aria-label="Вперёд">›</button></div></div><div class="calendar-grid ${S.calendar}">${S.calendar==='month'?['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<div class="month-weekday">${d}</div>`).join('')+Array.from({length:(new Date(start+'T12:00Z').getUTCDay()+6)%7},()=>'<div class="calendar-day blank" aria-hidden="true"></div>').join(''):''}${cards}</div><p class="note">${esc(zoneLabel(zone()))} · обновляется автоматически. Блокировка не отменяет существующие записи.</p><button class="secondary" id="block-time">Закрыть время для записи</button>`}
function freeTimeline(d,rows,blocks){const hours=S.own.schedule[new Date(d+'T12:00Z').getUTCDay()];if(!hours)return '<div class="closed-day">Выходной день</div>';const list=[];for(const h of Array.isArray(hours)?hours:[hours]){let cursor=fromLocal(d,h.start,zone()),end=fromLocal(d,h.end,zone());for(const b of [...rows.map(b=>({...b,starts_at:b.starts_at-(S.own.buffer||0)*60,ends_at:b.ends_at+(S.own.buffer||0)*60})),...blocks].sort((a,b)=>a.starts_at-b.starts_at)){if(b.starts_at>cursor)list.push([cursor,Math.min(b.starts_at,end)]);cursor=Math.max(cursor,b.ends_at)}if(cursor<end)list.push([cursor,end])}return `<div class="free-timeline"><h3>Свободные промежутки</h3>${list.filter(([a,b])=>b>a&&b>Date.now()/1000).map(([a,b])=>`<button data-manual data-start="${a}">${time(a)}–${time(b)} <span>＋ Запись</span></button>`).join('')||'<p class="note">Нет свободных промежутков</p>'}</div>`}
function clientsPage(){return `${heading('Клиенты','Люди, которые доверяют вам своё время.')}<label class="search-label">${icon('user')}<input id="client-search" type="search" placeholder="Имя или телефон" aria-label="Найти клиента"></label><div class="client-grid">${S.clients.map(x=>`<button class="person-card" data-client="${esc(x.id)}" data-search="${esc((x.name+' '+x.phone).toLowerCase())}">${imageTag('',x.name,'small-avatar')}<div><h3>${esc(x.name)}</h3><p>${esc(x.phone)}</p><small>${x.visits} завершённых визитов${x.last_visit?' · '+dateLabel(date(x.last_visit)):''}</small></div>${icon('arrow')}</button>`).join('')||empty('Здесь появятся ваши клиенты','Отправьте персональную ссылку. После первой записи клиент появится здесь.',button('Поделиться ссылкой','share'))}</div>`}
function more(){return `${heading('Мой кабинет',S.own.name)}<div class="more-grid">${[['services','grid','Услуги','Цены, описание и порядок'],['share','link','Персональная ссылка','Короткий адрес, QR-код и просмотр'],['analytics','calendar','Статистика','Завершённые и запланированные визиты'],['settings','settings','Настройки','Профиль, место работы, рабочее время и правила'],['subscription','clock','Подписка',trialText(S.own)||'7 дней бесплатно · затем 590 ₽/месяц'],['profile','user','Помощь','Знакомство с Тактом и уведомления']].map(([p,i,t,d])=>`<button class="more-card" data-page="${p}"><span>${icon(i)}</span><div><h3>${t}</h3><p>${d}</p></div>${icon('arrow')}</button>`).join('')}</div>`}
function subscriptionPage(){const x=S.own.subscription||{},trial=x.status==='trial',expired=x.status==='expired',untilDate=x.trial_ends_at?new Date(x.trial_ends_at*1000).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}):'';return `${heading('Подписка','Один тариф — весь Takt.')}<section class="editor-card subscription-card"><span class="eyebrow">${trial?'ПРОБНЫЙ ПЕРИОД':expired?'ТРЕБУЕТ ПРОДЛЕНИЯ':'ПОДПИСКА АКТИВНА'}</span><div class="subscription-price">590 ₽ <small>/ месяц</small></div>${trial?`<p><b>7 дней бесплатно.</b> Доступ до ${esc(untilDate)} · осталось ${x.days_left||0} дн.</p>`:expired?'<p><b>Пробный период закончился.</b> Все ваши данные сохранены.</p>':`<p>Подписка активна${x.paid_until?' до '+new Date(x.paid_until*1000).toLocaleDateString('ru-RU'):''}.</p>`}<div class="subscription-features"><span>✓ Онлайн-запись</span><span>✓ Расписание и клиенты</span><span>✓ Услуги и ссылка</span><span>✓ Автоматические напоминания</span><span>✓ Подтверждение визита</span><span>✓ Статистика</span></div>${x.payment_url?`<a class="primary wide" href="${esc(x.payment_url)}" target="_blank" rel="noopener">Продолжить за 590 ₽ / месяц</a>`:'<p class="note">Платёжный способ будет подключён отдельно. Пробный период работает уже сейчас.</p>'}<p class="note">Клиенты пользуются Takt бесплатно по вашей ссылке.</p></section>`}
function servicesPage(){return `${heading('Мои услуги','Порядок карточек определяет порядок на странице клиента.','<button class="primary" data-edit-service="new">＋ Услуга</button>')}<div class="service-cards">${S.own.services.map((x,i)=>`<article class="service-card ${x.active?'':'hidden-service'}" draggable="true" data-service-card="${x.id}">${x.photo?`<img src="${esc(x.photo)}" alt="${esc(x.name)}">`:''}<span class="service-visibility">${x.active?'На странице записи':'Скрыта от клиентов'}</span><h2>${esc(x.name)}</h2><strong>${x.duration} мин · ${money(x.price)}</strong><p>${esc(x.description||'Добавьте описание — клиенту будет легче выбрать.')}</p><div class="actions"><button class="secondary" data-edit-service="${x.id}">Редактировать</button><button class="text-button" data-hide-service="${x.id}">${x.active?'Скрыть':'Показать'}</button><button class="sort-button" data-sort="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Поднять услугу">↑</button><button class="sort-button" data-sort="${i}" data-direction="1" ${i===S.own.services.length-1?'disabled':''} aria-label="Опустить услугу">↓</button></div></article>`).join('')||empty('Добавьте первую услугу','Она появится на вашей странице записи.','<button class="primary" data-edit-service="new">Добавить услугу</button>')}</div><p class="note">На компьютере карточки можно перетаскивать. На телефоне используйте стрелки.</p>`}
function sharePage(){return `${heading('Ваша ссылка для записи','Одна ссылка — прямой путь к вашим услугам.')}<section class="share-card"><div class="success-icon">${icon('link')}</div>${imageTag(S.own.photo,S.own.name)}<h2>${esc(S.own.name)}</h2><p>Разместите ссылку в Telegram, Instagram, WhatsApp, VK, Avito или на своём сайте.</p>${!S.own.username?'<p class="note">Выберите короткое имя для своей страницы ниже.</p>':''}<label>Персональная ссылка<input readonly value="${link(S.own.id)}" aria-label="Персональная ссылка"></label><div class="actions"><button class="primary" id="share-link">Поделиться</button><button class="secondary" id="copy-link">Скопировать</button><button class="secondary" id="qr-link">QR-код</button></div><button class="text-button" id="preview">Посмотреть глазами клиента ${icon('arrow')}</button><form id="handle-form"><label>Имя вашей страницы<input name="username" value="${esc(S.own.username||'')}" pattern="[a-zA-Z][a-zA-Z0-9-]{2,31}" minlength="3" maxlength="32" placeholder="davud" required autocapitalize="none"><small>Латинские буквы, цифры и дефис. Старые ссылки сохранятся.</small></label><div class="form-error" role="alert"></div><button class="secondary">Сохранить адрес</button></form></section>`}
function settingsPage(){const x=S.own;return `${heading('Настройки','Ваше дело — по вашим правилам.','<button class="secondary" id="preview">Глазами клиента</button>')}<section class="editor-card"><form id="settings-form"><details class="settings-section" open><summary>Профиль <small>Как вас видят клиенты</small></summary>${photoField('settings',x.photo)}<label>Имя или название<input name="name" value="${esc(x.name)}" required minlength="2" maxlength="80"></label><div class="form-grid"><label>Профессия<input name="profession" value="${esc(x.profession||'')}" maxlength="80" placeholder="Например, барбер"></label><label>Сфера<select name="category">${Object.entries(cats).map(([v,t])=>`<option value="${v}" ${x.category===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label>Описание<textarea name="tagline" maxlength="160">${esc(x.tagline)}</textarea></label><div class="form-grid"><label>Телефон<input name="phone" value="${esc(x.phone)}" maxlength="24" type="tel"></label><label>Telegram<input name="telegram" value="${esc(x.telegram||'')}" maxlength="33" placeholder="@username" autocapitalize="none"></label></div><label>Формат работы<select name="format">${[['salon','У меня / в салоне'],['visit','Выезд к клиенту'],['online','Онлайн']].map(([v,t])=>`<option value="${v}" ${x.format===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Адрес<input name="address" value="${esc(x.address)}" maxlength="200" placeholder="Улица, дом"></label><div class="location-grid"><label>Салон / студия<input name="venue_name" value="${esc(x.venue_name||'')}" maxlength="80" placeholder="Название места"></label><label>Этаж<input name="floor" value="${esc(x.floor||'')}" maxlength="30" placeholder="Например, 2 этаж"></label><label>Кабинет<input name="room" value="${esc(x.room||'')}" maxlength="40" placeholder="Например, 205"></label><label>Вход / подъезд<input name="entrance" value="${esc(x.entrance||'')}" maxlength="100" placeholder="Со стороны двора"></label><label class="wide">Как пройти<textarea name="directions" maxlength="500" placeholder="Короткий ориентир для клиента">${esc(x.directions||'')}</textarea></label><label class="wide">Ссылка на карту<input name="map_url" type="url" value="${esc(x.map_url||'')}" maxlength="500" placeholder="https://..."></label></div><label>Часовой пояс<select name="timezone">${[...new Set([x.timezone,'Europe/Kaliningrad','Europe/Moscow','Europe/Samara','Asia/Yekaterinburg','Asia/Omsk','Asia/Krasnoyarsk','Asia/Irkutsk','Asia/Yakutsk','Asia/Vladivostok','Asia/Magadan','Asia/Kamchatka','Europe/Berlin','Asia/Dubai','Asia/Almaty','Asia/Tbilisi','Asia/Yerevan','America/New_York'])].filter(Boolean).map(z=>`<option value="${z}" ${x.timezone===z?'selected':''}>${esc(zoneLabel(z))}</option>`).join('')}</select><small>В этом поясе клиент видит время записи. Уже созданные встречи сохраняют свой момент времени.</small></label></details><details class="settings-section"><summary>Рабочее время <small>Дни, часы и перерывы</small></summary>${scheduleFields(x.schedule)}</details><details class="settings-section"><summary>Исключения <small>Закрытые часы, выходные и отпуск</small></summary><p class="note">Закройте один день или любой период. Существующие встречи сохраняются: сначала перенесите их при необходимости.</p><button type="button" class="secondary" id="block-time">Закрыть период</button></details><details class="settings-section"><summary>Правила записи <small>Ваши условия для клиентов</small></summary><div class="form-grid"><label>За сколько заранее можно записаться<select name="min_notice">${[[0,'Без ограничения'],[30,'30 минут'],[60,'1 час'],[120,'2 часа'],[180,'3 часа'],[360,'6 часов'],[720,'12 часов'],[1440,'24 часа']].map(([v,t])=>`<option value="${v}" ${x.min_notice===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Запись вперёд, дней<input type="number" name="horizon" value="${x.horizon}" min="1" max="180" required></label><label>Перерыв между клиентами, минут<input type="number" name="buffer" value="${x.buffer}" min="0" max="240" required></label><label>Отмена не позднее чем за, часов<input type="number" name="cancel_hours" value="${x.cancel_hours}" min="0" max="168" required></label></div><label class="toggle-row"><span>Разрешить клиентам перенос</span><input type="checkbox" name="allow_reschedule" ${x.allow_reschedule?'checked':''}></label><p class="note">Срок отмены применяется и к переносу. 0 часов — до начала встречи.</p></details><details class="settings-section"><summary>Уведомления <small>Важное приходит в Telegram</small></summary>${[['created','Новая запись'],['cancelled','Отмена записи'],['moved','Перенос записи'],['reminders','Подтверждение визита клиентом за 24 часа'],['client_2h','Клиенту за 2 часа'],['master_2h','Мне за 2 часа до клиента'],['client_events','Клиенту: подтверждение, отмена и перенос'],['daily_summary','Итоги моего дня'],['master_reminder','Дополнительно: мне за 1 час'],['summary','Дополнительно: утренняя сводка в 08:00']].map(([k,t])=>`<label class="toggle-row"><span>${t}</span><input type="checkbox" name="notify_${k}" ${x.notifications?.[k]?'checked':''}></label>`).join('')}<label>Во сколько присылать итоги дня<input type="time" name="summary_time" value="${esc(x.summary_time||'20:00')}" required><small>В вашем часовом поясе. По умолчанию — 20:00.</small></label><p class="note">Основные уведомления включены автоматически. За 24 часа клиент подтверждает визит; если ответа нет, за 2 часа Takt мягко напомнит ещё раз.</p><div id="delivery-status" class="note"></div></details><div class="form-error" role="alert"></div><button class="primary wide" type="submit">Сохранить настройки</button></form></section>`}
function analyticsPage(){const done=S.bookings.filter(b=>b.status==='done'),planned=S.bookings.filter(future);return `${heading('Статистика','По последним 500 записям вашего кабинета.')}<section class="today-summary"><div><span>Завершено визитов</span><strong>${done.length}</strong></div><div><span>Стоимость завершённых</span><strong>${money(done.reduce((a,b)=>a+b.price,0))}</strong></div><div><span>Ожидаемая стоимость</span><strong>${money(planned.reduce((a,b)=>a+b.price,0))}</strong></div></section><section class="editor-card"><h2>Услуги, которые выбирают</h2>${S.own.services.map(s=>{const n=done.filter(b=>b.service_id===s.id).length;return `<div class="analytics-row"><span>${esc(s.name)}</span><strong>${n} визитов</strong><meter value="${n}" max="${Math.max(done.length,1)}"></meter></div>`}).join('')||'<p>Добавьте услуги, чтобы начать.</p>'}<p class="note">Это стоимость услуг по записям, а не отчёт об оплатах. Онлайн-оплаты не подключены.</p></section>`}
function clientPage(){const x=S.tenant;if(!x)return empty('Нужна ссылка специалиста','Откройте приглашение вашего мастера. Если ссылка не работает, попросите прислать новую.');const route=x.map_url||(x.address?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(x.address):''),place=x.format==='visit'?'Специалист работает с выездом':x.format==='online'?'Встреча проходит онлайн':x.address||'Место встречи уточнит специалист',location=x.format==='salon'&&(x.address||x.venue_name||x.directions)?`<section class="location-card"><h3>Где встречаемся</h3>${x.venue_name?`<p><b>${esc(x.venue_name)}</b></p>`:''}${x.address?`<p>📍 ${esc(x.address)}</p>`:''}${x.floor||x.room?`<p>${[x.floor,x.room&&'кабинет '+x.room].filter(Boolean).map(esc).join(' · ')}</p>`:''}${x.entrance?`<p>${esc(x.entrance)}</p>`:''}${x.directions?`<p>${esc(x.directions)}</p>`:''}<div class="actions">${route?`<a class="primary" href="${esc(route)}" target="_blank" rel="noopener">Построить маршрут</a>`:''}${x.telegram?`<a class="secondary" href="https://t.me/${esc(x.telegram)}" target="_blank" rel="noopener">Связаться</a>`:''}</div></section>`:'';return `<section class="specialist-cover">${imageTag(x.photo,x.name)}<span class="eyebrow">${esc(x.profession||cats[x.category]||'Специалист')}</span><h1>${esc(x.name)}</h1><p>${esc(x.tagline)}</p><div class="specialist-contact">${icon('pin')}<span>${esc(place)}</span></div>${x.telegram?`<a class="text-button" href="https://t.me/${esc(x.telegram)}" target="_blank" rel="noopener">Написать специалисту</a>`:''}<div id="client-next" class="client-next"></div>${x.phone?`<a href="tel:${esc(x.phone.replace(/[^+0-9]/g,''))}" class="text-button">${esc(x.phone)}</a>`:''}</section>${location}<div class="section-heading"><h2>Выберите услугу</h2><span>${x.services.length}</span></div><div class="client-services">${x.services.map(s=>`<article class="client-service">${s.photo?`<img src="${esc(s.photo)}" alt="${esc(s.name)}">`:''}<div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><span>${s.duration} мин · ${money(s.price)}</span></div><button class="primary" data-book="${s.id}">Записаться</button></article>`).join('')||empty('Услуги пока не опубликованы','Свяжитесь со специалистом, чтобы уточнить возможность записи.')}<p class="note">Часовой пояс: ${esc(zoneLabel(x.timezone))}. ${x.cancel_hours?'Отмена и перенос минимум за '+x.cancel_hours+' ч до визита.':'Отменить можно до начала визита.'}</p></div>`}
function myBookings(){if(!S.me)return login();const all=S.bookings.filter(b=>!S.tenant||b.company_id===S.tenant.id),rows=all.filter(b=>S.tab==='upcoming'?future(b):!future(b));return `${heading('Мои записи',S.tenant?.name||'Ваши визиты')}<div class="segmented">${[['upcoming','Предстоящие'],['history','История']].map(([v,t])=>`<button data-tab="${v}" class="${S.tab===v?'selected':''}">${t}</button>`).join('')}</div><div class="visits">${rows.sort((a,b)=>S.tab==='upcoming'?a.starts_at-b.starts_at:b.starts_at-a.starts_at).map(b=>bookingCard(b)).join('')||empty(S.tab==='upcoming'?'Здесь появится ваша запись':'История начнётся с первого визита','Выберите услугу и удобное время у своего специалиста.',button('Записаться','client'))}</div>`}
function profile(){return `${heading(isClient()?'Мой профиль':'Помощь и аккаунт',isClient()?'Всё для ваших визитов.':'Такт всегда под рукой.')}<section class="editor-card">${imageTag('',S.me?.name)}<h2>${esc(S.me?.name||'Гость')}</h2><p class="note">${isClient()?'Ваши записи доступны только вам и специалисту. Уведомления приходят автоматически после запуска бота.':'Вы управляете только своим пространством. Уведомления Takt работают автоматически.'}</p><div class="actions"><button class="secondary" id="guide">Короткое знакомство</button></div></section>${!isClient()&&S.me?.owner?'<section class="editor-card"><h3>Подключение Telegram · владелец</h3><button class="secondary" id="connect-bot">Обновить настройки бота</button></section>':''}`}
function openSheet(title,html){sheet.scrollTop=0;sheet.innerHTML=`<div class="sheet-grip"></div><div class="dialog-head"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Закрыть">×</button></div>${html}`;if(!sheet.open)sheet.showModal()}
function serviceEditor(id){const s=S.own.services.find(x=>x.id===id)||{name:'',description:'',price:1500,duration:60,photo:'',active:1,position:S.own.services.length};S.photo=s.photo;openSheet(id==='new'?'Новая услуга':'Редактировать услугу',`<form id="service-form" data-id="${s.id||''}" data-key="${crypto.randomUUID()}">${photoField('service',s.photo)}<label>Название<input name="name" value="${esc(s.name)}" required minlength="2" maxlength="120"></label><label>Описание<textarea name="description" maxlength="700">${esc(s.description)}</textarea></label><div class="form-grid"><label>Стоимость, ₽<input name="price" type="number" value="${s.price}" min="0" max="1000000" required></label><label>Длительность, мин<input name="duration" type="number" value="${s.duration}" min="15" max="480" step="5" required></label></div><input type="hidden" name="position" value="${s.position}"><input type="hidden" name="active" value="${s.active}"><div class="form-error" role="alert"></div><button class="primary wide">Сохранить услугу</button></form>`)}
function blockEditor(){openSheet('Закрыть время',`<p class="note">Выберите часы, выходной или отпуск. В периоде не должно быть активных записей.</p><form id="block-form"><label class="toggle-row"><span>Закрыть дни целиком</span><input name="whole_days" type="checkbox"></label><div class="form-grid"><label>Начало<input type="date" name="date" min="${day()}" value="${S.date<day()?day():S.date}" required><input type="time" name="start" value="09:00" required></label><label>Окончание<input type="date" name="end_date" min="${day()}" value="${S.date<day()?day():S.date}" required><input type="time" name="end" value="20:00" required></label></div><label>Причина · только для вас<input name="label" maxlength="80" placeholder="Например, отпуск"></label><div class="form-error" role="alert"></div><button class="primary wide">Закрыть время</button></form>`)}
async function manualEditor(reset=true){if(!S.own.services.some(s=>s.active)){toast('Сначала добавьте доступную услугу');return}if(reset){manualClient=null;manualNewClient={name:'',phone:''};booking=null}openSheet('Кого записать?',skeleton());try{S.clients=await api('/v2/clients?company='+S.own.id);openSheet('Кого записать?',`<button class="primary wide" id="manual-new">＋ Новый клиент</button><label class="search-label"><input id="manual-search" placeholder="Имя или телефон" aria-label="Найти клиента"></label><div class="manual-clients">${S.clients.map(x=>`<button class="more-card" data-manual-client="${esc(x.id)}" data-search="${esc((x.name+' '+x.phone).toLowerCase())}"><div><h3>${esc(x.name)}</h3><p>${esc(x.phone)}</p></div>${icon('arrow')}</button>`).join('')||'<p class="note">Добавьте первого клиента по имени и телефону.</p>'}</div>`)}catch(e){openSheet('Не удалось загрузить клиентов',`<p>${esc(e.message)}</p><button class="primary" data-manual>Повторить</button>`)}}
function manualNewClientEditor(){openSheet('Новый клиент',`<form id="manual-client-form"><label>Имя<input name="name" value="${esc(manualNewClient.name)}" required minlength="2" maxlength="80" autocomplete="name"></label><label>Телефон<input name="phone" type="tel" value="${esc(manualNewClient.phone)}" required minlength="10" maxlength="24" autocomplete="tel"></label><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="secondary" id="manual-back-clients">Назад</button><button class="primary">Выбрать услугу</button></div></form>`)}
function manualServices(){openSheet('Выберите услугу',`<p class="note">Клиент: ${esc(manualClient.name)}</p><div class="manual-services">${S.own.services.filter(s=>s.active).map(s=>`<button class="more-card" data-manual-service="${s.id}"><div><h3>${esc(s.name)}</h3><p>${s.duration} мин · ${money(s.price)}</p></div>${icon('arrow')}</button>`).join('')}</div><div class="actions"><button class="secondary" id="manual-back-clients">Назад</button></div>`)}
async function startBooking(id,manual=false,move=null){if(!S.me){openSheet('Вход через Telegram',login());return}const tenant=manual?S.own:S.tenant,s=tenant?.services.find(x=>x.id===id)||move&&{id:move.service_id,name:move.service_name,duration:(move.ends_at-move.starts_at)/60,price:move.price};if(!tenant||!s)return;const previous=manual&&booking?.manual&&!booking.move?booking:null,sameClient=previous&&((previous.client_id&&previous.client_id===manualClient?.id)||(!previous.client_id&&previous.phone===manualClient?.phone));booking={tenant,s,manual,move,key:crypto.randomUUID(),step:0,date:manual?(previous?.date||manualDate):day(),at:manual?(previous?.at||null):null,name:manual?manualClient?.name||previous?.name||'':S.me.name,phone:manual?manualClient?.phone||previous?.phone||'':'',details:manual&&sameClient?previous.details||'':'',client_id:manual?manualClient?.id:undefined,known:manual&&!!manualClient,month:manual?(previous?.month||(previous?.date||manualDate).slice(0,7)):day().slice(0,7),availability:{}};if(!manual&&!move){try{const contact=await api('/v4/contact?company='+tenant.id);if(contact.phone){booking.name=contact.name;booking.phone=contact.phone;booking.known=true}}catch{}}await bookingSheet()}
function bookingCalendar(b){const start=b.month+'-01',n=new Date(Number(b.month.slice(0,4)),Number(b.month.slice(5)),0).getDate(),offset=(new Date(start+'T12:00Z').getUTCDay()+6)%7;return `<div class="booking-calendar"><div class="calendar-month-head"><button class="secondary" data-book-month="-1" aria-label="Предыдущий месяц" ${b.month<=day().slice(0,7)?'disabled':''}>‹</button><strong>${new Date(start+'T12:00Z').toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</strong><button class="secondary" data-book-month="1" aria-label="Следующий месяц" ${b.month>=day(b.tenant.horizon||30).slice(0,7)?'disabled':''}>›</button></div><div class="booking-month-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(t=>`<span>${t}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:n},(_,i)=>{const d=shift(start,i),info=b.availability[d],allowed=d>=day()&&d<=day(b.tenant.horizon||30)&&info?.count>0;return `<button data-book-date="${d}" aria-label="${dateLabel(d)}${allowed?' · есть время':' · недоступно'}" class="${d===b.date?'selected':''}" ${allowed?'':'disabled'}>${i+1}${allowed?'<i></i>':''}</button>`}).join('')}</div></div>`}
async function bookingSheet(){const epoch=++calendarRequest,b=booking;if(!b)return;if(b.step===0){openSheet(b.move?'Перенести запись':'Выберите дату и время',`<p class="dialog-sub">${esc(b.s.name)} · ${b.s.duration} мин · ${money(b.s.price)}</p><div id="booking-calendar">${skeleton()}</div><div id="available-slots" class="slots">${skeleton()}</div><p class="note">${esc(zoneLabel(zone()))}</p><div class="sticky-actions">${b.manual&&!b.move?'<button class="secondary" id="manual-back-services">Назад</button>':''}<button class="primary wide" id="booking-next" disabled>${b.move?'Перенести на это время':'Продолжить'}</button></div><div class="form-error" role="alert"></div>`);try{const dates=await api('/availability?company='+b.tenant.id+'&service='+b.s.id+'&date='+b.month+'-01&days=31'+(b.move?'&booking='+b.move.id:''));if(epoch!==calendarRequest||booking!==b||!sheet.open)return;for(const d of dates)b.availability[d.date]=d;if(!b.date.startsWith(b.month))b.date=dates.find(d=>d.date.startsWith(b.month)&&d.count>0)?.date||b.month+'-01';sheet.querySelector('#booking-calendar').innerHTML=bookingCalendar(b);await loadSlots()}catch(e){if(epoch===calendarRequest&&booking===b&&sheet.open){sheet.querySelector('#available-slots').innerHTML='<p>Не удалось загрузить данные</p><button class="secondary" id="retry-slots">Повторить</button>';sheet.querySelector('#booking-calendar').innerHTML=''}}}
else if(b.step===1){openSheet('Контакты для встречи',`<p class="dialog-sub">${dateLabel(b.date)} · ${time(b.at)} · ${esc(b.s.name)}</p><form id="booking-contact"><label>Имя<input name="name" value="${esc(b.name)}" minlength="2" maxlength="80" required autocomplete="given-name"></label><label>Телефон<input name="phone" type="tel" value="${esc(b.phone)}" minlength="10" maxlength="24" required autocomplete="tel"></label><label>${b.tenant.category==='cleaning'?'Адрес и площадь':b.tenant.category==='auto'?'Автомобиль и задача':'Комментарий'}<textarea name="details" maxlength="1200" ${['cleaning','auto'].includes(b.tenant.category)?'required minlength="5"':''}>${esc(b.details)}</textarea></label><label class="consent"><input type="checkbox" required><span>Передать контакты ${b.manual?'для оформления записи':'специалисту для обработки моей заявки'}.</span></label><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="secondary" id="booking-back">Назад</button><button class="primary">Проверить запись</button></div></form>`)}
else openSheet('Ваша запись',`<div class="booking-review"><span class="eyebrow">${esc(b.tenant.name)}</span><h2>${esc(b.s.name)}</h2><div><span>Дата и время</span><strong>${dateLabel(b.date)}, ${time(b.at)}</strong></div><div><span>Длительность</span><strong>${b.s.duration} мин</strong></div><div><span>Стоимость</span><strong>${money(b.s.price)}</strong></div><div><span>Клиент</span><strong>${esc(b.name)}</strong></div><div><span>Телефон</span><strong>${esc(b.phone)}</strong></div><p class="note">Без онлайн-оплаты. ${b.manual?'Запись появится в вашем календаре.':'Специалист подтвердит вашу заявку.'}</p><div class="form-error" role="alert"></div><div class="actions"><button class="secondary" id="booking-back">Назад</button><button class="primary" id="booking-submit">${b.manual?'Добавить запись':'Подтвердить запись'}</button></div></div>`)}
let slotRequest=0,calendarRequest=0;
async function loadSlots(){const n=++slotRequest,b=booking,selectedAt=b.at;try{const slots=await api('/slots?company='+b.tenant.id+'&service='+b.s.id+'&date='+b.date+(b.move?'&booking='+b.move.id:''));if(n!==slotRequest||booking!==b||!sheet.open)return;const selectedValid=selectedAt&&slots.includes(selectedAt);b.at=selectedValid?selectedAt:null;sheet.querySelector('#available-slots').innerHTML=slots.length?slots.map(t=>`<button class="slot ${selectedValid&&t===selectedAt?'active':''}" data-slot="${t}">${time(t)}</button>`).join(''):'<div class="no-slots"><h3>На этот день свободного времени нет</h3><p>Ищем ближайший доступный день…</p></div>';const nextButton=sheet.querySelector('#booking-next');if(nextButton)nextButton.disabled=!selectedValid;if(!slots.length){const next=await api('/next-slot?company='+b.tenant.id+'&service='+b.s.id+'&date='+b.date+(b.move?'&booking='+b.move.id:''));if(n!==slotRequest||booking!==b||!sheet.open)return;sheet.querySelector('#available-slots').innerHTML=next.date?`<div class="no-slots"><h3>На этот день свободного времени нет</h3><p>Ближайшее время: ${dateLabel(next.date)} · ${time(next.starts_at)}</p><button class="secondary" data-book-date="${next.date}">Показать</button></div>`:'<div class="no-slots"><h3>Все доступные даты заняты</h3><p>Свяжитесь со специалистом, чтобы подобрать время.</p></div>'}}catch(e){if(n===slotRequest&&sheet.open)sheet.querySelector('#available-slots').textContent=e.message}}
async function submitBooking(el){el.disabled=true;try{if(!booking.manual)await requestMessages();const b=booking;if(b.move)await post('/v2/reschedule',{id:b.move.id,starts_at:b.at});else await post('/bookings',{company_id:b.tenant.id,service_id:b.s.id,starts_at:b.at,name:b.name,phone:b.phone,details:b.details,request_key:b.key,manual:b.manual,client_id:b.manual?b.client_id:undefined});openSheet('Готово',`<section class="success"><div class="success-icon">${icon('check')}</div><h2>${b.move?'Запись перенесена':'Вы записаны'}</h2><p>${esc(b.tenant.name)}<br>${dateLabel(b.date)} · ${time(b.at)} · ${esc(zoneLabel(zone()))}</p><button class="primary wide" id="booking-finished">${b.manual?'Открыть календарь':'Мои записи'}</button>${!b.manual?'<p class="note">Подтверждение и напоминания отправляются автоматически в Telegram.</p>':''}</section>`);tg?.HapticFeedback?.notificationOccurred('success')}catch(e){if(e.status===409){booking.step=0;booking.availability={};await bookingSheet();sheet.querySelector('.form-error').textContent='Это время только что заняли. Выберите другое свободное окно.'}else{sheet.querySelector('.form-error').textContent=e.message;el.disabled=false}}}
function visitActions(id){const b=S.bookings.find(x=>x.id===id);if(!b)return;const admin=!isClient(),allowed=active(b)&&(admin||b.starts_at>Date.now()/1000+(S.tenant?.cancel_hours||0)*3600);openSheet('Детали записи',`<div class="booking-review"><h3>${esc(b.service_name)}</h3><p>${dateLabel(date(b.starts_at))} · ${time(b.starts_at)}–${time(b.ends_at)}</p><span class="badge ${b.status}">${labels[b.status]}</span>${admin?(()=>{const a=attendanceInfo(b);return `<span class="attendance visit-confirmation ${a[0]}">${a[1]}</span>`})():''}<p>${esc(b.name)} · ${esc(b.phone)}</p>${b.details?`<p>${esc(b.details)}</p>`:''}<strong>${money(b.price)}</strong></div><div class="sheet-actions">${admin&&b.status==='pending'?`<button class="primary" data-status="confirmed" data-id="${id}">Подтвердить</button>`:''}${admin&&b.status==='confirmed'&&b.ends_at<Date.now()/1000?`<button class="primary" data-status="done" data-id="${id}">Завершить визит</button>`:''}${allowed?` ${admin||S.tenant?.allow_reschedule?`<button class="secondary" data-move="${id}">Перенести</button>`:''}<button class="danger" data-cancel="${id}">Отменить запись</button>`:''}</div><div class="form-error" role="alert"></div>`)}
function clientDetails(id){const x=S.clients.find(x=>x.id===id);if(!x)return;openSheet(x.name,`<p><a href="tel:${esc(x.phone.replace(/[^+0-9]/g,''))}">${esc(x.phone)}</a></p><div class="client-summary"><span>${x.visits} завершённых визитов</span><strong>${money(x.revenue)}</strong></div><p class="note">${x.next_visit?'Ближайший визит: '+dateLabel(date(x.next_visit))+' · '+time(x.next_visit):'Нет предстоящих визитов'}</p><form id="note-form" data-client="${esc(id)}"><label>Ваша личная заметка<textarea name="note" maxlength="2000">${esc(x.note)}</textarea></label><div class="form-error" role="alert"></div><button class="secondary">Сохранить заметку</button></form><h3>История записей</h3>${S.bookings.filter(b=>b.user_id===id).map(b=>`<div class="history-line"><strong>${dateLabel(date(b.starts_at))} · ${time(b.starts_at)}</strong><span>${esc(b.service_name)}</span><small>${labels[b.status]} · ${money(b.price)}</small></div>`).join('')}`)}
async function reorder(from,to){const all=[...S.own.services];if(to<0||to>=all.length)return;const [x]=all.splice(from,1);all.splice(to,0,x);await post('/v2/reorder',{company_id:S.own.id,ids:all.map(s=>s.id)});await refreshOwn();await render()}
async function copyLink(){try{await navigator.clipboard.writeText(link(S.own.id));toast('Ссылка скопирована')}catch{openSheet('Ваша ссылка',`<input readonly value="${link(S.own.id)}" aria-label="Скопируйте ссылку">`)}}
async function shareLink(){const url=link(S.own.id);if(navigator.share){try{await navigator.share({title:S.own.name,text:'Запишитесь ко мне онлайн 👇\n\nВыберите услугу и удобное время:',url});return}catch(e){if(e.name==='AbortError')return}}if(tg?.openTelegramLink){tg.openTelegramLink('https://t.me/share/url?url='+encodeURIComponent(url)+'&text='+encodeURIComponent('Запишитесь ко мне онлайн 👇\n\nВыберите услугу и удобное время:'));return}await copyLink()}
async function click(e){const el=e.target.closest('button');if(!el)return;try{
if(el.hasAttribute('data-close')){sheet.close();slotRequest++;return}
if(el.id==='retry-slots'){await bookingSheet();return}
if(el.dataset.bookMonth){const d=new Date(booking.month+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()+Number(el.dataset.bookMonth));booking.month=d.toISOString().slice(0,7);await bookingSheet();return}
if(el.dataset.manualClient){manualClient=S.clients.find(c=>c.id===el.dataset.manualClient);manualServices();return}
if(el.id==='manual-back-clients'){const form=sheet.querySelector('#manual-client-form');if(form){const fd=new FormData(form);manualNewClient={name:String(fd.get('name')||''),phone:String(fd.get('phone')||'')}}await manualEditor(false);return}
if(el.id==='manual-back-services'){manualServices();return}
if(el.id==='manual-new'){manualNewClientEditor();return}
if(el.dataset.copyDay!==undefined){const i=Number(el.dataset.copyDay),form=document.querySelector('#settings-form')||document.querySelector('#register-form'),hours=readSchedule(new FormData(form));openSheet('Применить расписание',`<form id="copy-days-form" data-source="${i}"><p class="note">Выберите дни. Изменения сохранятся вместе с расписанием.</p>${[1,2,3,4,5,6,0].filter(d=>d!==i).map(d=>`<label class="toggle-row"><span>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]}</span><input type="checkbox" name="target" value="${d}"></label>`).join('')}<button class="primary wide">Применить</button></form>`);return}
if(el.id==='retry-init'){await init();return}
if(el.id==='app-back'){await goBack();return}
if(el.id==='guide'){S.tour=true;S.tourStep=0;await render();scrollTo({top:0});return}
if(el.id==='skip-tour'){requestMessages();await finishTour();return}
if(el.hasAttribute('data-begin')){requestMessages();S.page=S.own?'dashboard':'register';await finishTour();return}
if(el.dataset.addInterval!==undefined){const i=el.dataset.addInterval,container=document.querySelector('[data-day-intervals="'+i+'"]'),ends=container.querySelectorAll('input[name="end'+i+'"]');if(ends.length>=8){toast('Максимум 8 интервалов');return}const end=ends.length?parseTime(ends[ends.length-1].value):480;container.insertAdjacentHTML('beforeend',intervalInputs(i,{start:Math.min(end+60,1380),end:Math.min(end+180,1435)}));return}
if(el.hasAttribute('data-remove-interval')){if(el.closest('.work-intervals').children.length>1)el.closest('.work-interval').remove();else toast('Выключите день, чтобы сделать его выходным');return}
if(el.id==='learn-more'){document.querySelector('#how-it-works')?.scrollIntoView({behavior:'smooth'});return}
if(el.id==='enter-client'){S.mode='client';S.tenant=null;S.page='my';await render();return}
if(el.dataset.page){booking=null;S.page=el.dataset.page;await render();scrollTo({top:0});return}
if(el.id==='refresh'){await render();return}
if(el.id==='register-back'){saveDraft();S.step--;await render();return}
if(el.dataset.calendar){S.calendar=el.dataset.calendar;await render();return}
if(el.dataset.date){S.date=el.dataset.date;S.calendar='day';await render();return}
if(el.dataset.shift){if(S.calendar==='month'){const d=new Date(S.date+'T12:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+Number(el.dataset.shift));S.date=d.toISOString().slice(0,10)}else S.date=shift(S.date,Number(el.dataset.shift)*(S.calendar==='week'?7:1));await render();return}
if(el.id==='today'){S.date=day();await render();return}
if(el.hasAttribute('data-manual')){manualDate=el.dataset.start?date(Number(el.dataset.start)):S.page==='calendar'?S.date:day();manualAt=el.dataset.start?Number(el.dataset.start):null;booking=null;manualEditor(true);return}
if(el.dataset.manualService){await startBooking(el.dataset.manualService,true);if(manualAt){const slot=sheet.querySelector('[data-slot="'+manualAt+'"]');slot?.click()}return}
if(el.id==='block-time'){blockEditor();return}
if(el.dataset.unblock){openSheet('Открыть время?',`<p class="note">Этот промежуток снова станет доступен для записи.</p><button class="primary wide" data-delete-block="${el.dataset.unblock}">Открыть время</button>`);return}
if(el.dataset.deleteBlock){await api('/v2/blocks',{method:'DELETE',body:JSON.stringify({company_id:S.own.id,id:el.dataset.deleteBlock})});sheet.close();await render();return}
if(el.dataset.editService){serviceEditor(el.dataset.editService);return}
if(el.dataset.hideService){const s=S.own.services.find(x=>x.id===el.dataset.hideService);await post('/v2/services',{...s,active:!s.active});await refreshOwn();await render();toast(s.active?'Услуга скрыта':'Услуга доступна клиентам');return}
if(el.dataset.sort!==undefined){await reorder(Number(el.dataset.sort),Number(el.dataset.sort)+Number(el.dataset.direction));return}
if(el.id==='copy-link'){await copyLink();return}
if(el.id==='share-link'){await shareLink();return}
if(el.id==='qr-link'){const {default:qrcode}=await import('./qr.js');const qr=qrcode(0,'M');qr.addData(link(S.own.id));qr.make();openSheet('QR-код для записи',`<div class="qr-card">${qr.createSvgTag({cellSize:5,margin:4})}<h3>${esc(S.own.name)}</h3><p class="note">Клиент наведёт камеру и откроет вашу страницу записи.</p><a class="secondary" href="data:image/svg+xml;charset=utf-8,${encodeURIComponent(qr.createSvgTag({cellSize:8,margin:4}))}" download="takt-qr.svg">Скачать QR-код</a></div>`);return}
if(el.id==='preview'){S.tenant=await api('/v2/page/'+S.own.id);S.mode='client';S.preview=true;S.page='client';await render();scrollTo({top:0});return}
if(el.id==='exit-preview'){S.mode='specialist';S.preview=false;S.page='share';await render();return}
if(el.dataset.book){if(S.preview){toast('Это предпросмотр. Клиенты смогут записаться по вашей ссылке.');return}await startBooking(el.dataset.book);return}
if(el.dataset.bookDate){booking.date=el.dataset.bookDate;booking.month=booking.date.slice(0,7);await bookingSheet();return}
if(el.dataset.slot){booking.at=Number(el.dataset.slot);sheet.querySelectorAll('[data-slot]').forEach(b=>b.classList.toggle('active',b===el));sheet.querySelector('#booking-next').disabled=false;return}
if(el.id==='booking-next'){if(booking.move){await submitBooking(el);return}booking.step=booking.known&&!['cleaning','auto'].includes(booking.tenant.category)?2:1;await bookingSheet();return}
if(el.id==='booking-back'){const contact=sheet.querySelector('#booking-contact');if(contact)Object.assign(booking,Object.fromEntries(new FormData(contact)));booking.step=booking.known&&booking.step===2?0:booking.step-1;await bookingSheet();return}
if(el.id==='booking-submit'){await submitBooking(el);return}
if(el.id==='booking-finished'){sheet.close();S.page=booking.manual?'calendar':'my';S.date=booking.date;S.tab='upcoming';await render();return}
if(el.dataset.tab){S.tab=el.dataset.tab;await render();return}
if(el.dataset.visit){visitActions(el.dataset.visit);return}
if(el.dataset.cancel){openSheet('Отменить запись?',`<p class="note">Время освободится для других клиентов. Вернуть запись можно будет только заново.</p><button class="danger wide" data-status="cancelled" data-id="${el.dataset.cancel}">Да, отменить</button><div class="form-error" role="alert"></div>`);return}
if(el.dataset.status){el.disabled=true;await api('/bookings/'+el.dataset.id,{method:'PATCH',body:JSON.stringify({status:el.dataset.status})});sheet.close();await render();toast('Статус обновлён');return}
if(el.dataset.move){const b=S.bookings.find(x=>x.id===el.dataset.move);manualDate=date(b.starts_at);await startBooking(b.service_id,!isClient(),b);return}
if(el.dataset.client){clientDetails(el.dataset.client);return}
if(el.id==='notifications'){await requestMessages(true);return}
if(el.id==='connect-bot'){el.disabled=true;await post('/telegram/setup',{});toast('Настройки бота обновлены');el.disabled=false;return}
}catch(err){const target=sheet.open?sheet.querySelector('.form-error'):null;if(target)target.textContent=err.message;else toast(err.message);el.disabled=false}}
root.addEventListener('click',click);sheet.addEventListener('click',click);
async function submit(e){e.preventDefault();const form=e.target,fd=new FormData(form),b=Object.fromEntries(fd),btn=form.querySelector('button[type="submit"]')||form.querySelector('button:not([type="button"])'),error=form.querySelector('.form-error');if(btn)btn.disabled=true;if(error)error.textContent='';try{
if(form.id==='manual-client-form'){manualNewClient={name:b.name,phone:b.phone};manualClient={name:b.name,phone:b.phone};manualServices();return}
if(form.id==='copy-days-form'){const origin=document.querySelector('#settings-form')||document.querySelector('#register-form'),source=Number(form.dataset.source),hours=readSchedule(new FormData(origin));for(const target of fd.getAll('target')){const check=origin.querySelector('[name="day'+target+'"]');check.checked=!!hours[source];origin.querySelector('[data-day-intervals="'+target+'"]').innerHTML=(hours[source]||[{start:540,end:1080}]).map(d=>intervalInputs(target,d)).join('')}sheet.close();toast('Расписание применено. Сохраните изменения.');return}
if(form.id==='register-form'){if(S.step===2)await requestMessages();saveDraft();if(S.step<2){S.step++;await render();scrollTo({top:0});return}const result=await post('/v2/register',{...S.draft,price:Number(S.draft.price),duration:Number(S.draft.duration)});S.me=await api('/me');await refreshOwn();S.page='share';await render();toast('Ваша страница готова');return}
if(form.id==='service-form'){await post('/v2/services',{...b,price:Number(b.price),duration:Number(b.duration),position:Number(b.position),active:Number(b.active),company_id:S.own.id,id:form.dataset.id||undefined,request_key:form.dataset.key,photo:S.photo});sheet.close();await refreshOwn();await render();toast('Услуга сохранена');return}
if(form.id==='handle-form'){await post('/v2/handle',{company_id:S.own.id,username:b.username});await refreshOwn();await render();toast('Ваш адрес сохранён');return}
if(form.id==='settings-form'){await post('/v2/settings',{...b,min_notice:Number(b.min_notice),horizon:Number(b.horizon),buffer:Number(b.buffer),allow_reschedule:fd.has('allow_reschedule'),notifications:Object.fromEntries(['created','cancelled','moved','reminders','client_2h','master_2h','client_events','daily_summary','summary','master_reminder'].map(k=>[k,fd.has('notify_'+k)])),company_id:S.own.id,photo:S.own.photo,cancel_hours:Number(b.cancel_hours),schedule:readSchedule(fd)});await refreshOwn();await render();toast('Настройки сохранены');return}
if(form.id==='block-form'){await post('/v2/blocks',{company_id:S.own.id,starts_at:b.whole_days?Math.max(Math.floor(Date.now()/1000)+1,unix(b.date,'00:00')):unix(b.date,b.start),ends_at:b.whole_days?unix(shift(b.end_date,1),'00:00'):unix(b.end_date,b.end),label:b.label});sheet.close();await render();toast('Время закрыто');return}
if(form.id==='note-form'){await post('/v2/client-note',{company_id:S.own.id,client_id:form.dataset.client,note:b.note});sheet.close();await render();toast('Заметка сохранена');return}
if(form.id==='booking-contact'){Object.assign(booking,b);booking.step=2;await bookingSheet();return}
}catch(err){if(error)error.textContent=err.message;else toast(err.message)}finally{if(btn)btn.disabled=false}}
root.addEventListener('submit',submit);sheet.addEventListener('submit',submit);
async function change(e){const el=e.target;try{if(el.id==='demo-role'){S.role=el.value;await init()}if(el.id==='calendar-date'){S.date=el.value;await render()}if(el.id==='booking-date'){booking.date=el.value;await bookingSheet()}if(el.dataset.photo){const file=el.files?.[0];if(!file)return;if(file.size>15*1024*1024)throw Error('Выберите фото размером до 15 МБ');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=320;canvas.height=320;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,320,320);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.65);if(el.dataset.photo==='draft')S.draft.photo=photo;else if(el.dataset.photo==='settings')S.own.photo=photo;else S.photo=photo;const preview=el.closest('label').querySelector('.upload-avatar');preview.outerHTML=imageTag(photo,'Фото','upload-avatar');toast('Фото добавлено')}}catch(err){toast(err.message)}}
root.addEventListener('change',change);sheet.addEventListener('change',change);
function filterClients(e){if(['client-search','manual-search'].includes(e.target.id)){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q))}}
root.addEventListener('input',filterClients);sheet.addEventListener('input',filterClients);
let dragged=null;root.addEventListener('dragstart',e=>{dragged=e.target.closest('[data-service-card]')?.dataset.serviceCard||null});root.addEventListener('dragover',e=>{if(e.target.closest('[data-service-card]'))e.preventDefault()});root.addEventListener('drop',async e=>{e.preventDefault();const target=e.target.closest('[data-service-card]')?.dataset.serviceCard;if(!target||!dragged||target===dragged)return;try{await reorder(S.own.services.findIndex(x=>x.id===dragged),S.own.services.findIndex(x=>x.id===target))}catch(err){toast(err.message)}dragged=null});

sheet.addEventListener('close',()=>slotRequest++);
async function updateFree(){if(S.page!=='dashboard'||!S.own||S.tour)return;const s=S.own.services.find(x=>x.active),target=document.querySelector('#free-count');if(!target)return;if(!s){target.textContent='—';return}try{const slots=await api('/slots?company='+S.own.id+'&service='+s.id+'&date='+day());if(document.querySelector('#free-count')===target){target.textContent=slots.length;document.querySelector('#free-label').textContent='для «'+s.name+'»'}}catch{target.textContent='—'}}
const observer=new MutationObserver(()=>{if(document.querySelector('#free-count')?.textContent==='…')updateFree()});observer.observe(root,{childList:true,subtree:true});
setInterval(async()=>{if(pollBusy||document.hidden||sheet.open||S.tour||!S.me)return;if(!['dashboard','calendar','my'].includes(S.page))return;pollBusy=true;try{const previous=JSON.stringify([S.bookings,S.blocks]);if(isClient())S.bookings=await api('/bookings');else await workData();if(previous!==JSON.stringify([S.bookings,S.blocks])){const y=scrollY;await render();scrollTo({top:y})}}catch{}finally{pollBusy=false}},5000);
initDisplay(tg,toast);init();
initMobile(tg);
async function goBack(){if(sheet.open){const back=sheet.querySelector('#booking-back,#manual-back-services,#manual-back-clients');if(back){back.click();return}sheet.close();return}if(S.preview){document.querySelector('#exit-preview')?.click();return}if(S.page==='register'&&S.step){saveDraft();S.step--;await render();return}S.page=isClient()?'client':S.own?(['services','settings','share','analytics','subscription','profile'].includes(S.page)?'more':'dashboard'):'landing';await render();scrollTo({top:0})}
tg?.BackButton?.onClick(goBack);
function updateBack(){const show=sheet.open||S.preview||!['dashboard','client','landing'].includes(S.page);try{show?tg?.BackButton?.show():tg?.BackButton?.hide()}catch{}}
new MutationObserver(updateBack).observe(root,{childList:true,subtree:true});new MutationObserver(updateBack).observe(sheet,{attributes:true,attributeFilter:['open']});

async function loadDeliveryStatus(){try{const x=await api('/v4/delivery?company='+S.own.id),target=document.querySelector('#delivery-status');if(target){const issue=(x.blocked||0)+(x.failed||0)+(x.unknown||0)+(x.sending||0);target.textContent=issue?'Есть сообщения без подтверждённой доставки. Takt продолжит обработку автоматически.':'Уведомления работают автоматически.'}}catch{}}

async function loadClientNext(){const target=document.querySelector('#client-next'),tenant=S.tenant,service=tenant?.services[0];if(!target||!service)return;try{const x=await api('/next-slot?company='+tenant.id+'&service='+service.id+'&date='+day(-1));if(document.querySelector('#client-next')!==target)return;target.innerHTML=x.date?`Ближайшее время · ${esc(service.name)}<br><b>${dateLabel(x.date)}, ${time(x.starts_at)}</b>`:'Ближайшие даты заняты. Свяжитесь со специалистом.'}catch{}}

let messageAllowed=!!tg?.initDataUnsafe?.user?.allows_write_to_pm,messageRequest=null;
function requestMessages(force=false){if(messageAllowed&&!force)return Promise.resolve(true);if(messageRequest)return messageRequest;if(!tg?.requestWriteAccess){if(force)toast('Откройте чат с ботом и нажмите /start, чтобы получать сообщения.');return Promise.resolve(false)}messageRequest=new Promise(resolve=>{let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(timer);messageAllowed=!!ok;messageRequest=null;if(ok)post('/v5/notifications',{}).catch(()=>{});if(force)toast(ok?'Сообщения разрешены':'Разрешение можно дать позже в чате бота.');resolve(!!ok)};const timer=setTimeout(()=>finish(false),20000);try{tg.requestWriteAccess(finish)}catch{finish(false)}});return messageRequest}
function adminPage(){const a=S.admin,t=a.totals,counts=[['Специалисты',t.specialists],['Клиентские профили',t.clients],['Все записи',t.bookings],['Новые кабинеты · 24 ч',t.registrations],['Активные пользователи · 24 ч',t.active]],states={sent:'Доставлено',queued:'В очереди',retry:'Ожидают повтора',blocked:'Бот заблокирован',failed:'Не доставлено',unknown:'Доставка не подтверждена',sending:'Отправляются'},errors={DELIVERY_UNKNOWN:'Telegram не подтвердил доставку',DELIVERY_FAILED:'Сбой фоновой отправки',REQUEST_FAILED:'Не удалось обработать запрос','403':'Получатель запретил сообщения','429':'Telegram ограничил частоту','400':'Telegram отклонил сообщение'};return `${heading('Контроль Takt','Только для администратора','<button class="secondary" id="refresh">Обновить</button>')}<div class="admin-metrics">${counts.map(([label,n])=>`<article class="editor-card"><strong>${n}</strong><p>${label}</p></article>`).join('')}</div><section class="editor-card"><h2>Уведомления · последние 24 часа</h2><p class="note">${a.bot_configured?'Бот подключён':'Токен бота не настроен'}</p><div class="admin-states">${a.delivery.map(x=>`<div><span>${states[x.state]||'Обработано'}</span><b>${x.count}</b></div>`).join('')||'<p class="note">Отправленных сообщений пока нет.</p>'}</div><p class="note">Неподтверждённая доставка не повторяется автоматически, чтобы не прислать сообщение дважды.</p></section><section class="editor-card"><h2>Фоновые задачи</h2>${a.tasks.map(t=>`<p><b>${t.name==='bot-menu-v5'?'Кнопка Telegram':'Напоминания и итоги дня'}</b><br>${t.state==='error'?'Требуется проверка':t.name!=='bot-menu-v5'&&a.checked_at-t.started_at>900?'Давно не запускались':t.state==='running'?'Выполняются':'Работают'}<br><small>Последний запуск: ${new Date(t.started_at*1000).toLocaleString('ru-RU')}</small></p>`).join('')||'<p class="note">Ожидаем первый запуск. Проверка проходит каждую минуту.</p>'}</section><section class="editor-card"><h2>Ошибки · последние 24 часа</h2>${a.errors.map(e=>`<p>${errors[e.code]||'Сервис временно не ответил'} <b>× ${e.count}</b></p>`).join('')||'<p class="note">Зарегистрированных ошибок нет.</p>'}</section>`}
